 models.measure=(l,v)=>{const n=random(5,20),d=pick([1,2,3,4]),length=n*d;if(v%3===0)return numeric(`В ряд без промежутков уложили ${n} одинаковых бусин. Длина ряда ${length} мм. Найдите диаметр бусины.`,d,'мм','Метод рядов уменьшает относительную погрешность измерения размера малого тела.','d = L/N',[`${length} : ${n} = ${d}.`],{kind:'divide',a:length,b:n});if(v%3===1){const a=random(1,5)*10,b=a+random(2,8)*10,k=random(4,10);return numeric(`Между отметками ${a} и ${b} шкалы ${k} равных промежутков. Найдите цену деления.`,(b-a)/k,'единицах шкалы','Цена деления — разность соседних подписанных значений, делённая на число промежутков.','c = (b − a)/N',[`(${b} − ${a}) : ${k} = ${fmt((b-a)/k)}.`],{kind:'scale',a,b,k})}const a=random(10,50);return numeric(`Результат измерения длины ${a} см. Выразите его в метрах.`,a/100,'м','В одном метре 100 сантиметров.','l(м) = l(см)/100',[`${a}/100 = ${fmt(a/100)}.`],{kind:'divide',a,b:100})};
 models.average=(l,v)=>{const a=random(2,8),b=random(2,8),t1=random(2,5),t2=l>1?random(2,8):t1;return numeric(`Тело ${t1} с двигалось со скоростью ${a} м/с, затем ${t2} с — со скоростью ${b} м/с. Найдите среднюю скорость за весь путь.`,(a*t1+b*t2)/(t1+t2),'м/с','Средняя скорость равна всему пути, делённому на всё время; среднее арифметическое скоростей применимо только при равных временах.','vср = (v₁t₁ + v₂t₂)/(t₁ + t₂)',[`${a}·${t1} + ${b}·${t2} = ${a*t1+b*t2} м.`,`Всё время ${t1+t2} с.`],{kind:'average',a,b,t1,t2})};
 models.forceSum=(l,v)=>{const a=random(2,8)*5,b=random(1,5)*5,opposite=v%2===1,value=opposite?Math.abs(a-b):a+b;return numeric(`На тело вдоль одной прямой действуют силы ${a} Н и ${b} Н, направленные ${opposite?'в противоположные стороны':'в одну сторону'}. Найдите модуль равнодействующей.`,value,'Н','Сонаправленные силы складывают, противоположные вычитают; модуль неотрицателен.',opposite?'R = |F₁ − F₂|':'R = F₁ + F₂',[`${opposite?'|'+a+' − '+b+'|':a+' + '+b} = ${value}.`],{kind:'forces',a,b,opposite})};
 models.displacement=(l,v)=>{const a=random(2,6),b=random(1,a-1);return numeric(`Ученик прошёл ${a} м вправо и ${b} м влево по прямой. Найдите ${v%2?'путь':'модуль перемещения'}.`,v%2?a+b:a-b,'м','Путь — сумма длин всех участков. Перемещение соединяет начальную и конечную точки.',v%2?'s = a + b':'|Δx| = |a − b|',[`${v%2?a+' + '+b:a+' − '+b} = ${v%2?a+b:a-b}.`],{kind:'forces',a,b,opposite:v%2===0})};
 models.temperature=(l,v)=>{const t=pick([-20,-10,0,10,20,30,50]),reverse=v%2===1;return numeric(reverse?`Температура ${t+273} К. Найдите температуру по Цельсию. В этой задаче используйте 273.`:`Температура ${t} °C. Найдите абсолютную температуру. В этой задаче используйте 273.`,reverse?t:t+273,reverse?'°C':'К','В учебном приближении T = t + 273. Разность температур в кельвинах и градусах Цельсия одинакова.',reverse?'t = T − 273':'T = t + 273',[reverse?`${t+273} − 273 = ${t}.`:`${t} + 273 = ${t+273}.`],{kind:'sum',values:reverse?[t+273,-273]:[t,273]})};
 models.balance=(l,v)=>{const m1=random(1,4),m2=random(1,4),t1=random(5,8)*10,t2=random(1,3)*10;return numeric(`Смешали ${m1} кг воды при ${t1} °C и ${m2} кг воды при ${t2} °C. Теплопотерями и теплоёмкостью сосуда пренебречь. Найдите конечную температуру.`,(m1*t1+m2*t2)/(m1+m2),'°C','Тепло, отданное горячей водой, равно теплу, полученному холодной. Для одного вещества c сокращается.','T = (m₁t₁ + m₂t₂)/(m₁ + m₂)',[`(${m1}·${t1} + ${m2}·${t2})/(${m1}+${m2}) = ${fmt((m1*t1+m2*t2)/(m1+m2))}.`],{kind:'average',a:t1,b:t2,t1:m1,t2:m2})};
 models.thermo=(l,v)=>{const Q=random(5,15)*100,A=random(1,4)*100;return numeric(`Газ получил ${Q} Дж теплоты и совершил работу ${A} Дж. На сколько изменилась его внутренняя энергия?`,Q-A,'Дж','В записи Q = ΔU + A работа A — работа газа над внешними телами.','ΔU = Q − A',[`${Q} − ${A} = ${Q-A}.`],{kind:'sum',values:[Q,-A]})};
 models.efficiency=(l,v)=>{const full=random(5,12)*100,percent=pick([20,25,40,50,60,75,80]),useful=full*percent/100;return numeric(`Устройство получило ${full} Дж энергии и выполнило полезную работу ${useful} Дж. Найдите КПД.`,percent,'%','КПД — отношение полезной энергии к затраченной. Для процентов умножьте отношение на 100.','η = Aпол/Q · 100%',[`${useful}/${full} · 100 = ${percent}.`],{kind:'percent',a:useful,b:full})};
 models.lever=(l,v)=>{const f=random(2,8)*10,a=random(1,5),b=random(1,5);return numeric(`Рычаг в равновесии. Первая сила ${f} Н, её плечо ${a} см; плечо второй силы ${b} см. Найдите вторую силу.`,f*a/b,'Н','При равновесии моменты противоположно вращающих сил равны. Одни единицы длины плеч сокращаются.','F₁l₁ = F₂l₂; F₂ = F₁l₁/l₂',[`${f}·${a}/${b} = ${fmt(f*a/b)}.`],{kind:'muldiv',a:f,b:a,c:b})};
 models.acceleration=(l,v)=>{const u=random(0,5),a=random(1,4),t=random(2,8),v1=u+a*t;return numeric(v%2?`Тело имело скорость ${u} м/с. Ускорение ${a} м/с² постоянно. Найдите скорость через ${t} с.`:`Скорость выросла с ${u} до ${v1} м/с за ${t} с. Найдите ускорение.`,v%2?v1:a,v%2?'м/с':'м/с²','При постоянном ускорении v = v₀ + at. Ускорение — изменение скорости за единицу времени.',v%2?'v = v₀ + at':'a = (v − v₀)/t',[v%2?`${u} + ${a}·${t} = ${v1}.`:`(${v1} − ${u})/${t} = ${a}.`],{kind:v%2?'velocity':'acceleration',u,a,t,v:v1})};
 models.motion=(l,v)=>{const u=l===1?0:random(1,5),a=random(1,4),t=random(2,8);return numeric(`Тело движется с постоянным ускорением ${a} м/с², начальная скорость ${u} м/с. Найдите перемещение за ${t} с.`,u*t+a*t*t/2,'м','Перемещение равно площади под графиком v(t). При постоянном ускорении s = v₀t + at²/2.','s = v₀t + at²/2',[`${u}·${t} + ${a}·${t}²/2 = ${fmt(u*t+a*t*t/2)}.`],{kind:'motion',u,a,t})};
 models.fall=(l,v)=>{const t=random(1,5);return numeric(`Тело свободно падает из состояния покоя ${t} с. Сопротивлением воздуха пренебречь, g = 10 м/с². Найдите ${v%2?'пройденный путь':'модуль скорости'}.`,v%2?5*t*t:10*t,v%2?'м':'м/с','Для падения без начальной скорости v = gt, h = gt²/2.',v%2?'h = gt²/2':'v = gt',[v%2?`10·${t}²/2 = ${5*t*t}.`:`10·${t} = ${10*t}.`],{kind:v%2?'motion':'velocity',u:0,a:10,t})};
 models.projectile=(l,v)=>{const vx=random(2,8),t=random(1,5),height=5*t*t;return numeric(`Тело бросили горизонтально со скоростью ${vx} м/с с высоты ${height} м. Сопротивлением пренебречь, g = 10 м/с². Найдите дальность полёта.`,vx*t,'м','Вертикальное движение определяет время полёта, горизонтальное — дальность.','t = √(2h/g); L = v₀t',[`t = √(2·${height}/10) = ${t} с.`,`L = ${vx}·${t} = ${vx*t} м.`],{kind:'projectile',vx,height,g:10})};
 models.relative=(l,v)=>{const a=random(8,15),b=random(2,7),same=v%2===1;return numeric(`Два автомобиля движутся по прямой со скоростями ${a} и ${b} м/с ${same?'в одном направлении':'навстречу друг другу'}. Найдите модуль скорости первого относительно второго.`,same?a-b:a+b,'м/с','Относительная скорость — векторная разность. При встречном движении модули складываются, при одном направлении вычитаются.',same?'vотн = |v₁ − v₂|':'vотн = v₁ + v₂',[`${a} ${same?'−':'+'} ${b} = ${same?a-b:a+b}.`],{kind:'forces',a,b,opposite:same})};
 models.collision=(l,v)=>{const a=random(1,5),b=random(1,5),u=random(2,10);return numeric(`Тело ${a} кг движется со скоростью ${u} м/с и неупруго сталкивается с покоящимся телом ${b} кг. После удара тела движутся вместе. Внешним импульсом пренебречь. Найдите общую скорость.`,a*u/(a+b),'м/с','При неупругом столкновении сохраняется импульс системы; кинетическая энергия в общем случае не сохраняется.','v = m₁v₁/(m₁ + m₂)',[`${a}·${u}/(${a}+${b}) = ${fmt(a*u/(a+b))}.`],{kind:'collision',a,b,u})};
 models.weight=(l,v)=>{const m=random(2,8),a=random(1,4),up=v%2===0;return numeric(`Лифт с телом массой ${m} кг имеет ускорение ${a} м/с², направленное ${up?'вверх':'вниз'}. g = 10 м/с². Найдите вес тела.`,m*(10+(up?a:-a)),'Н','Вес — сила действия тела на опору. При ускорении вверх P = m(g+a), вниз P = m(g−a).',up?'P = m(g + a)':'P = m(g − a)',[`${m}·(10 ${up?'+':'−'} ${a}) = ${m*(10+(up?a:-a))}.`],{kind:'weight',m,a,up})};
 models.gravitation=(l,v)=>{const f=random(1,6)*10,k=pick([2,3,4]);return numeric(`Две материальные точки притягиваются с силой ${f} Н. Расстояние между ними увеличили в ${k} раза, массы не изменили. Найдите новую силу.`,f/(k*k),'Н','Закон тяготения даёт обратную пропорциональность квадрату расстояния.','F₂ = F₁/k²',[`${f}/${k}² = ${fmt(f/(k*k))}.`],{kind:'divide',a:f,b:k*k})};
 models.echo=(l,v)=>{const t=pick([.2,.4,.5,1,2]),speed=340;return numeric(`Эхо вернулось через ${fmt(t)} с после короткого звука. Скорость звука ${speed} м/с. Найдите расстояние до отражающей поверхности.`,speed*t/2,'м','Звук прошёл путь до препятствия и обратно. Полный путь делят на два.','L = vt/2',[`${speed}·${fmt(t)}/2 = ${fmt(speed*t/2)}.`],{kind:'muldiv',a:speed,b:t,c:2})};
 models.pendulum=(l,v)=>{const length=pick([.1,.4,.9,1.6]),g=10;return numeric(`Длина математического маятника ${fmt(length)} м. Колебания малые; g = 10 м/с², π = 3,14. Найдите период.`,6.28*Math.sqrt(length/g),'с','Формула математического маятника применима при малых колебаниях, когда размер груза мал по сравнению с длиной нити.','T = 2π√(l/g)',[`T = 6,28·√(${fmt(length)}/10) = ${fmt(6.28*Math.sqrt(length/g))}.`],{kind:'pendulum',length,g})};
 models.springPeriod=(l,v)=>{const m=pick([.1,.2,.4,.8]),k=pick([10,20,40,80]);return numeric(`Груз массой ${fmt(m)} кг совершает малые колебания на идеальной пружине жёсткостью ${k} Н/м. π = 3,14. Найдите период.`,6.28*Math.sqrt(m/k),'с','Период пружинного маятника зависит от массы и жёсткости.','T = 2π√(m/k)',[`T = 6,28·√(${fmt(m)}/${k}) = ${fmt(6.28*Math.sqrt(m/k))}.`],{kind:'pendulum',length:m,g:k})};
 models.harmonic=(l,v)=>{const A=random(1,5),w=random(1,5);return numeric(`Гармоническое движение: x(t) = ${A}cos(${w}t), координата в метрах, время в секундах. Найдите ${v%2?'максимальный модуль ускорения':'максимальный модуль скорости'}.`,v%2?A*w*w:A*w,v%2?'м/с²':'м/с','Для x = A cos(ωt) максимальная скорость Aω, максимальное ускорение Aω².',v%2?'aₘ = Aω²':'vₘ = Aω',[`${A}·${w}${v%2?'²':''} = ${v%2?A*w*w:A*w}.`],{kind:'product',k:1,a:A,b:w,p:1,q:v%2?2:1})};
 models.series=(l,v)=>{const a=random(2,8),b=random(2,8),parallel=v%2===1;return numeric(`Сопротивления ${a} Ом и ${b} Ом соединены ${parallel?'параллельно':'последовательно'}. Найдите общее сопротивление.`,parallel?a*b/(a+b):a+b,'Ом','Последовательно сопротивления складывают. Для двух параллельных R = R₁R₂/(R₁+R₂).',parallel?'R = R₁R₂/(R₁+R₂)':'R = R₁ + R₂',[parallel?`${a}·${b}/(${a}+${b}) = ${fmt(a*b/(a+b))}.`:`${a}+${b} = ${a+b}.`],{kind:'circuit',a,b,parallel})};
 models.capJoin=(l,v)=>{const a=random(1,6),b=random(1,6),series=v%2===1;return numeric(`Конденсаторы ${a} мкФ и ${b} мкФ соединены ${series?'последовательно':'параллельно'}. Найдите общую ёмкость.`,series?a*b/(a+b):a+b,'мкФ','При параллельном соединении ёмкости складываются. При последовательном складываются обратные ёмкости.',series?'C = C₁C₂/(C₁+C₂)':'C = C₁ + C₂',[series?`${a}·${b}/(${a}+${b}) = ${fmt(a*b/(a+b))}.`:`${a}+${b} = ${a+b}.`],{kind:'circuit',a,b,parallel:series})};
 models.fullCircuit=(l,v)=>{const E=random(6,24),R=random(2,8),r=random(1,3);return numeric(`ЭДС источника ${E} В, внутреннее сопротивление ${r} Ом, внешнее ${R} Ом. Найдите ток в замкнутой цепи.`,E/(R+r),'А','Для полной цепи учитывают и внешнее, и внутреннее сопротивление.','I = ε/(R + r)',[`${E}/(${R}+${r}) = ${fmt(E/(R+r))}.`],{kind:'fullCircuit',E,R,r})};
 models.coulomb=(l,v)=>{const a=random(1,5),b=random(1,5),r=pick([.1,.2,.3,.5]);return numeric(`Модули двух точечных зарядов ${a} мкКл и ${b} мкКл; расстояние ${fmt(r)} м. k = 9·10⁹ Н·м²/Кл². Найдите модуль силы взаимодействия в вакууме.`,.009*a*b/(r*r),'Н','Заряды переведите из мкКл в Кл. В формуле учитывают квадрат расстояния.','F = k|q₁q₂|/r²',[`1 мкКл = 10⁻⁶ Кл; множитель k·10⁻¹² = 0,009.`,`F = 0,009·${a}·${b}/${fmt(r)}² = ${fmt(.009*a*b/(r*r))}.`],{kind:'coulomb',a,b,r})};
 models.gas=(l,v)=>{const T=pick([200,250,300,400]),V=random(1,5),p=random(1,4)*100,k=pick([2,3]);return numeric(v%2?`Идеальный газ при неизменном объёме имеет давление ${p} кПа и температуру ${T} К. Температуру увеличили в ${k} раза. Найдите новое давление.`:`Газ при постоянной температуре имеет давление ${p} кПа и объём ${V} л. Объём увеличили в ${k} раза. Найдите новое давление.`,v%2?p*k:p/k,'кПа',v%2?'При постоянном объёме p/T постоянно.':'При постоянной температуре pV постоянно.',v%2?'p₂ = p₁T₂/T₁':'p₂ = p₁V₁/V₂',[`${p} ${v%2?'·':':'} ${k} = ${fmt(v%2?p*k:p/k)}.`],{kind:'ratio',y:p,fa:k,fb:1,p:v%2?1:-1,q:0})};
 models.idealGas=(l,v)=>{const n=random(1,4),T=pick([200,250,300,400]),V=pick([.1,.2,.5,1]);return numeric(`Количество идеального газа ${n} моль, температура ${T} К, объём ${fmt(V)} м³. R = 8,3 Дж/(моль·К). Найдите давление.`,n*8.3*T/V,'Па','Уравнение Менделеева — Клапейрона: pV = νRT. Температура — абсолютная.','p = νRT/V',[`${n}·8,3·${T}/${fmt(V)} = ${fmt(n*8.3*T/V)}.`],{kind:'idealGas',n,T,V})};
 models.humidity=(l,v)=>{const saturated=pick([10,20,25,40]),p=random(2,8)*saturated/10;return numeric(`Плотность водяного пара ${fmt(p)} г/м³, плотность насыщенного пара при той же температуре ${saturated} г/м³. Найдите относительную влажность.`,p/saturated*100,'%','Сравнивать нужно плотности при одной температуре; единицы в отношении сокращаются.','φ = ρ/ρнас · 100%',[`${fmt(p)}/${saturated}·100 = ${fmt(p/saturated*100)}.`],{kind:'percent',a:p,b:saturated})};
 models.young=(l,v)=>{const stress=random(1,8)*10,strain=pick([.001,.002,.004]);return numeric(`Механическое напряжение при упругой деформации ${stress} МПа, относительное удлинение ${fmt(strain*100)}%. Найдите модуль Юнга в ГПа.`,stress/strain/1000,'ГПа','Модуль Юнга E = σ/ε. Относительную деформацию переводят из процентов в доли; 1 ГПа = 1000 МПа.','E = σ/ε',[`ε = ${fmt(strain*100)}/100 = ${strain}.`,`E = ${stress}/${strain}/1000 = ${fmt(stress/strain/1000)} ГПа.`],{kind:'young',stress,strain})};
 models.continuity=(l,v)=>{const a=random(2,6),b=random(1,4),speed=random(1,5);return numeric(`Несжимаемая жидкость течёт стационарно. Первое сечение ${a} см², скорость ${speed} м/с; второе сечение ${b} см². Найдите скорость во втором сечении.`,a*speed/b,'м/с','Объёмный расход несжимаемой жидкости постоянен: S₁v₁ = S₂v₂.','v₂ = S₁v₁/S₂',[`${a}·${speed}/${b} = ${fmt(a*speed/b)}.`],{kind:'muldiv',a,b:speed,c:b})};
 models.induction=(l,v)=>{const turns=random(2,8)*10,flux=random(1,8)/100,time=pick([.1,.2,.5,1]);return numeric(`Магнитный поток через каждый виток катушки из ${turns} витков равномерно изменился по модулю на ${fmt(flux)} Вб за ${fmt(time)} с. Найдите модуль ЭДС индукции.`,turns*flux/time,'В','Модуль ЭДС равен числу витков, умноженному на скорость изменения потока через один виток.','|ε| = N|ΔΦ|/Δt',[`${turns}·${fmt(flux)}/${fmt(time)} = ${fmt(turns*flux/time)}.`],{kind:'muldiv',a:turns,b:flux,c:time})};
 models.transformer=(l,v)=>{const u=random(2,8)*10,n1=random(2,8)*100,n2=random(1,6)*100;return numeric(`Идеальный трансформатор: U₁ = ${u} В, N₁ = ${n1}, N₂ = ${n2}. Найдите напряжение вторичной обмотки.`,u*n2/n1,'В','Для идеального трансформатора отношение напряжений равно отношению чисел витков.','U₂ = U₁N₂/N₁',[`${u}·${n2}/${n1} = ${fmt(u*n2/n1)}.`],{kind:'muldiv',a:u,b:n2,c:n1})};
 models.ac=(l,v)=>{const amplitude=random(2,8)*10;return numeric(`Синусоидальное напряжение имеет амплитуду ${amplitude} В. Примите √2 = 1,414. Найдите действующее напряжение.`,amplitude/1.414,'В','Действующее значение синусоидального напряжения в √2 раз меньше амплитуды.','U = Uₘ/√2',[`${amplitude}/1,414 = ${fmt(amplitude/1.414)}.`],{kind:'divide',a:amplitude,b:1.414})};
 models.lc=(l,v)=>{const L=pick([1,4,9,16]),C=pick([1,4,9]);return numeric(`Идеальный LC-контур: L = ${L} мГн, C = ${C} мкФ. Используйте π = 3,14 и √(10⁻⁹) = 3,1623·10⁻⁵. Найдите период в миллисекундах.`,.19859244*Math.sqrt(L*C),'мс','По формуле Томсона T = 2π√(LC). Переведите мГн и мкФ в СИ, затем секунды в миллисекунды.','T = 2π√(LC)',[`LC = ${L*C}·10⁻⁹ с².`,`T = 6,28·√(${L*C})·3,1623·10⁻⁵·1000 = ${fmt(.19859244*Math.sqrt(L*C))} мс.`],{kind:'lc',L,C})};
 models.reflection=(l,v)=>{const a=random(1,8)*10;return numeric(`Луч падает на плоское зеркало под углом ${a}° к нормали. Найдите ${v%2?'угол между падающим и отражённым лучами':'угол отражения'}.`,v%2?2*a:a,'градусах','Углы падения и отражения отсчитывают от нормали, они равны.',v%2?'γ = 2α':'β = α',[v%2?`2·${a} = ${2*a}.`:`β = ${a}°.`],{kind:'product',k:v%2?2:1,a,b:1,p:1,q:0})};
 models.refract=(l,v)=>{const n=pick([1.2,1.5,2]),c=3e8;return numeric(`Показатель преломления среды ${fmt(n)}. c = 3·10⁸ м/с. Найдите скорость света в среде в единицах 10⁸ м/с.`,3/n,'единицах 10⁸ м/с','Абсолютный показатель преломления n = c/v.','v = c/n',[`Коэффициент перед 10⁸: 3/${fmt(n)} = ${fmt(3/n)}.`],{kind:'divide',a:3,b:n})};
 models.lens=(l,v)=>{const f=pick([10,15,20,25]),a=f*pick([2,3,4]);return numeric(`Предмет перед тонкой собирающей линзой находится на расстоянии ${a} см; фокусное расстояние ${f} см. Найдите расстояние до действительного изображения.`,a*f/(a-f),'см','Для действительного предмета и изображения: 1/f = 1/a + 1/b.','b = af/(a − f)',[`${a}·${f}/(${a}−${f}) = ${fmt(a*f/(a-f))}.`],{kind:'lens',a,f})};
 models.diffraction=(l,v)=>{const d=pick([1,2,4]),sin=pick([.2,.3,.4]),order=pick([1,2]);return numeric(`Дифракционная решётка: период d = ${d} мкм; для максимума порядка ${order} sin θ = ${fmt(sin)}. Найдите длину волны в нм.`,d*sin/order*1000,'нм','Для главных максимумов d sin θ = kλ. Один микрометр равен 1000 нм.','λ = d sin θ/k',[`${d}·${fmt(sin)}/${order}·1000 = ${fmt(d*sin/order*1000)}.`],{kind:'diffraction',d,sin,order})};
 models.photoelectric=(l,v)=>{const energy=random(4,10),work=random(1,3);return numeric(`Энергия фотона ${energy} эВ, работа выхода металла ${work} эВ. Найдите максимальную кинетическую энергию фотоэлектрона.`,energy-work,'эВ','Уравнение Эйнштейна: энергия фотона идёт на работу выхода и кинетическую энергию.','Eк,max = hν − Aвых',[`${energy} − ${work} = ${energy-work}.`],{kind:'sum',values:[energy,-work]})};
 models.halflife=(l,v)=>{const n=random(1,4),N=random(2,8)*2**n,T=random(2,10);return numeric(`Первоначально было ${N} условных единиц радиоактивных ядер. Период полураспада ${T} суток. Сколько останется через ${n*T} суток?`,N/2**n,'условных единицах','За каждый период полураспада количество оставшихся ядер уменьшается вдвое.','N = N₀/2^(t/T)',[`t/T = ${n*T}/${T} = ${n}.`,`${N}/2^${n} = ${N/2**n}.`],{kind:'decay',N,T,time:n*T})};
 models.nuclear=(l,v)=>{const A=pick([12,16,23,27,56]),Z={12:6,16:8,23:11,27:13,56:26}[A];return numeric(`В ядре массовое число A = ${A}, зарядовое число Z = ${Z}. Сколько ${v%2?'протонов':'нейтронов'} в ядре?`,v%2?Z:A-Z,v%2?'протонах':'нейтронах','Зарядовое число Z — число протонов. Массовое число A — сумма протонов и нейтронов.',v%2?'Nпр = Z':'Nнейтр = A − Z',[v%2?`Число протонов ${Z}.`:`${A} − ${Z} = ${A-Z}.`],{kind:'sum',values:v%2?[Z]:[A,-Z]})};
 models.binding=(l,v)=>{const defect=pick([.01,.02,.04,.1]);return numeric(`Дефект массы ядра ${fmt(defect)} а.е.м. Используйте 1 а.е.м.·c² = 931,5 МэВ. Найдите энергию связи.`,defect*931.5,'МэВ','Энергия связи равна дефекту массы, умноженному на c². В данных единицах используют коэффициент 931,5.','Eсв = Δmc²',[`${fmt(defect)}·931,5 = ${fmt(defect*931.5)}.`],{kind:'product',k:931.5,a:defect,b:1,p:1,q:0})};
 models.nano=(l,v)=>{const n=random(1,9)*10;return numeric(`Размер наночастицы ${n} нм. Выразите его в микрометрах.`,n/1000,'мкм','1 мкм = 1000 нм.','l(мкм) = l(нм)/1000',[`${n}/1000 = ${fmt(n/1000)}.`],{kind:'divide',a:n,b:1000})};
 function concepts(id,rows){conceptData[id]=rows;models[id]=(level,variant)=>{const allowed=rows.filter(r=>(r[4]||1)<=level),eligible=allowed.length?allowed:rows.slice(0,1),row=eligible[variant%eligible.length];return theory(row[0],row[1],row[2],row[3])}}
