 models.nano=(l,v)=>{if(v%4===0)return originalModels.nano(l,v);if(v%4===1){const x=pick([.02,.04,.05,.1,.2]);return numeric(`Размер частицы ${fmt(x)} мкм. Переведите в нанометры.`,x*1000,'нм','Один микрометр содержит 1000 нанометров.','l(нм) = 1000l(мкм)',[`${fmt(x)}·1000 = ${fmt(x*1000)}.`],{kind:'product',k:1000,a:x,b:1,p:1,q:0})}const factor=pick([2,3,4]);return numeric(`Ребро кубической частицы уменьшили в ${factor} раза. Во сколько раз выросло отношение площади поверхности к объёму?`,factor,'разах','Для куба S = 6a², V = a³, поэтому S/V = 6/a. Уменьшение размера увеличивает удельную поверхность.','S/V = 6/a',[`Отношение обратно пропорционально ребру; оно вырастет в ${factor} раза.`],{kind:'product',k:1,a:factor,b:1,p:1,q:0})};
 models.halflife=(l,v)=>{if(v%4===0)return originalModels.halflife(l,v);const periods=random(1,4),T=random(2,10),initial=random(2,8)*2**periods,remaining=initial/2**periods;if(v%4===1)return numeric(`За ${T*periods} суток число нераспавшихся ядер уменьшилось с ${initial} до ${remaining} условных единиц. Найдите период полураспада.`,T,'сутках','Определите, сколько раз количество уменьшилось вдвое, затем разделите всё время на это число.','T = t/n',[`${initial}/${remaining} = 2^${periods}.`,`${T*periods}/${periods} = ${T}.`],{kind:'divide',a:T*periods,b:periods});if(v%4===2)return numeric(`Через сколько суток количество ядер уменьшится в ${2**periods} раза, если период полураспада ${T} суток?`,T*periods,'сутках','Каждое уменьшение вдвое требует одного периода полураспада.','t = nT',[`${2**periods} = 2^${periods}, поэтому t = ${periods}·${T}.`],{kind:'product',k:1,a:T,b:periods,p:1,q:1});return numeric(`Какая доля первоначального количества ядер в процентах останется через ${periods} периода полураспада?`,100/2**periods,'%','После n периодов остаётся доля 1/2ⁿ.','Доля = 100%/2ⁿ',[`100/${2**periods} = ${fmt(100/2**periods)}%.`],{kind:'divide',a:100,b:2**periods})};
 models.fullCircuit=(l,v)=>{if(v%4===0)return originalModels.fullCircuit(l,v);const I=random(1,4),R=random(2,8),r=random(1,3),E=I*(R+r),U=I*R;if(v%4===1)return numeric(`ЭДС ${E} В, внутреннее сопротивление ${r} Ом, внешнее ${R} Ом. Найдите напряжение на внешнем сопротивлении.`,U,'В','Сначала найдите ток полной цепи, затем напряжение внешнего участка.','I = ε/(R+r); U = IR',[`I = ${E}/(${R}+${r}) = ${I} А.`,`U = ${I}·${R} = ${U} В.`],{kind:'fullVoltage',E,R,r});if(v%4===2)return numeric(`Ток источника ${I} А; внешнее сопротивление ${R} Ом, внутреннее ${r} Ом. Найдите ЭДС.`,E,'В','ЭДС покрывает падение напряжения на внешнем и внутреннем сопротивлениях.','ε = I(R+r)',[`${I}·(${R}+${r}) = ${E}.`],{kind:'emf',I,R,r});return numeric(`ЭДС источника ${E} В, напряжение на его зажимах ${U} В при токе ${I} А. Найдите внутреннее сопротивление.`,r,'Ом','Разность ЭДС и напряжения на зажимах равна Ir.','r = (ε − U)/I',[`(${E}−${U})/${I} = ${r}.`],{kind:'internalR',E,U,I})};
 models.transformer=(l,v)=>{if(v%4===0)return originalModels.transformer(l,v);const n1=random(2,6)*100,n2=random(1,5)*100,u1=random(2,8)*20,u2=u1*n2/n1;if(v%4===1)return numeric(`Идеальный трансформатор имеет отношение U₂/U₁ = ${fmt(n2/n1)}. N₁ = ${n1}. Найдите N₂.`,round(n2/n1)*n1,'витках','В идеальном трансформаторе отношение напряжений равно отношению витков. Используйте указанное числовое отношение.','N₂ = N₁(U₂/U₁)',[`${n1}·${fmt(n2/n1)} = ${fmt(round(n2/n1)*n1)}.`],{kind:'product',k:1,a:n1,b:round(n2/n1),p:1,q:1});const I1=random(1,5),U1=random(10,20),U2=random(2,8);return numeric(`Идеальный трансформатор: U₁ = ${U1} В, I₁ = ${I1} А, U₂ = ${U2} В. Найдите I₂.`,U1*I1/U2,'А','В идеальном трансформаторе потерь нет: мощности первичной и вторичной обмоток равны.','U₁I₁ = U₂I₂',[`${U1}·${I1}/${U2} = ${fmt(U1*I1/U2)}.`],{kind:'muldiv',a:U1,b:I1,c:U2})};
 models.lc=(l,v)=>{if(v%4===0)return originalModels.lc(l,v);if(v%4===1){const factor=pick([4,9,16]);return numeric(`Индуктивность LC-контура увеличили в ${factor} раза при прежней ёмкости. Во сколько раз вырос период?`,Math.sqrt(factor),'разах','Период пропорционален квадратному корню из индуктивности.','T₂/T₁ = √(L₂/L₁)',[`√${factor} = ${Math.sqrt(factor)}.`],{kind:'sqrt',a:factor})}if(v%4===2){const T=pick([.2,.5,1,2]);return numeric(`Период электромагнитных колебаний ${fmt(T)} мс. Найдите частоту в кГц.`,1/T,'кГц','Частота обратна периоду. Обратная миллисекунда соответствует килогерцу.','ν = 1/T',[`1/${fmt(T)} = ${fmt(1/T)} кГц.`],{kind:'divide',a:1,b:T})}const C=random(1,5),U=random(2,8);return numeric(`В момент максимального напряжения конденсатор LC-контура имеет ёмкость ${C} мкФ и напряжение ${U} В. Найдите энергию электрического поля.`,C*U*U/2,'мкДж','Энергия заряженного конденсатора равна CU²/2.','W = CU²/2',[`${C}·${U}²/2 = ${fmt(C*U*U/2)}.`],{kind:'product',k:.5,a:C,b:U,p:1,q:2})};
 models.projectile=(l,v)=>{if(v%4===0)return originalModels.projectile(l,v);const vx=random(2,8),t=random(1,5),height=5*t*t;if(v%4===1)return numeric(`Тело брошено горизонтально с высоты ${height} м. g = 10 м/с², сопротивления нет. Найдите время полёта.`,t,'с','Вертикальная начальная скорость равна нулю. Время определяют по вертикальному падению.','t = √(2h/g)',[`√(2·${height}/10) = ${t}.`],{kind:'sqrt',a:2*height/10});if(v%4===2)return numeric(`Тело брошено горизонтально. Через ${t} с, до удара о землю, каков модуль вертикальной скорости? g = 10 м/с².`,10*t,'м/с','Вертикальная начальная скорость нулевая, ускорение равно g.','vᵧ = gt',[`10·${t} = ${10*t}.`],{kind:'velocity',u:0,a:10,t});return numeric(`Тело брошено горизонтально со скоростью ${vx} м/с. Найдите модуль скорости через ${t} с, до удара о землю. g = 10 м/с².`,Math.sqrt(vx*vx+100*t*t),'м/с','Горизонтальная и вертикальная скорости перпендикулярны.','v = √(vₓ² + vᵧ²), vᵧ = gt',[`vᵧ = ${10*t} м/с.`,`v = √(${vx}² + ${10*t}²) = ${fmt(Math.sqrt(vx*vx+100*t*t))}.`],{kind:'sqrt',a:vx*vx+100*t*t})};
